begin;
create extension if not exists pgcrypto;
create type public.membership_state as enum ('pending','approved','suspended','inactive');
create type public.app_role as enum ('student','instructor','admin','superadmin');
create type public.submission_state as enum ('draft','submitted','under_review','revision_requested','wrong_course','zero','positive','completed','suspended','invalidated','administrative_review');
create table public.departments(id uuid primary key default gen_random_uuid(),name text not null unique);
create table public.profiles(id uuid primary key references auth.users on delete restrict,display_name text not null default '',student_number text,degree text check(degree in ('bachelor','master','doctorate')),department_id uuid references public.departments,membership public.membership_state not null default 'pending',leaderboard_consent boolean not null default false,publication_consent boolean not null default false,created_at timestamptz not null default now());
create table public.roles(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,role public.app_role not null,department_id uuid references public.departments,approved boolean not null default false,unique nulls not distinct(user_id,role,department_id));
create table public.semesters(id uuid primary key default gen_random_uuid(),title text not null,starts_on date not null,ends_on date not null,check(ends_on>=starts_on));
create table public.offerings(id uuid primary key default gen_random_uuid(),title text not null,department_id uuid not null references public.departments,semester_id uuid not null references public.semesters,instructor_id uuid not null references public.profiles,approved boolean not null default false,unique(title,semester_id,instructor_id));
create table public.enrollments(student_id uuid not null references public.profiles,offering_id uuid not null references public.offerings,approved boolean not null default false,primary key(student_id,offering_id));
create table public.policies(id uuid primary key default gen_random_uuid(),name text not null,approved boolean not null default false,revision_hours integer check(revision_hours>=0),referral_hours integer check(referral_hours>=0),max_alternatives integer check(max_alternatives>=0),review_hours integer check(review_hours>0),unlimited_alternatives boolean not null default false,attendance_exceptions boolean not null default false,points_enabled boolean not null default false,certificates_enabled boolean not null default false,created_at timestamptz not null default now());
create table public.forms(id uuid primary key default gen_random_uuid(),version text not null unique,title text not null,object_path text not null,approved boolean not null default false);
create table public.events(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',speaker text,organizer text,starts_at timestamptz not null,ends_at timestamptz not null,venue text,online_url text,capacity integer check(capacity>0),registration_opens timestamptz,registration_closes timestamptz,club_approved boolean not null default false,summary_deadline timestamptz,form_id uuid references public.forms,policy_id uuid references public.policies,department_id uuid not null references public.departments,responsible_id uuid references public.profiles,attendance_method text not null default 'staff',status text not null default 'draft' check(status in ('draft','published','cancelled')),created_at timestamptz not null default now(),check(ends_at>=starts_at),check(summary_deadline is null or summary_deadline>=ends_at),check(registration_closes is null or registration_opens is null or registration_closes>=registration_opens));
create table public.event_offerings(event_id uuid references public.events,offering_id uuid references public.offerings,primary key(event_id,offering_id));
create table public.registrations(event_id uuid references public.events,student_id uuid references public.profiles,status text not null default 'registered' check(status in ('registered','cancelled')),created_at timestamptz not null default now(),primary key(event_id,student_id));
create table public.attendance(event_id uuid references public.events,student_id uuid references public.profiles,confirmed boolean not null default false,reason text not null,recorded_by uuid not null references public.profiles,updated_at timestamptz not null default now(),primary key(event_id,student_id));
create table public.submissions(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles,event_id uuid not null references public.events,state public.submission_state not null default 'draft',positive_locked boolean not null default false,deadline_snapshot timestamptz not null,policy_snapshot jsonb not null,form_id uuid not null references public.forms,created_at timestamptz not null default now(),unique(student_id,event_id));
create table public.attachments(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions,version integer not null check(version>0),object_path text not null unique,mime text not null check(mime in ('image/jpeg','image/png','image/webp','application/pdf')),bytes integer not null check(bytes>0 and bytes<=10485760),sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),safety text not null default 'pending' check(safety in ('pending','clean','rejected')),created_at timestamptz not null default now(),unique(submission_id,version));
create table public.referrals(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions,offering_id uuid not null references public.offerings,instructor_id uuid not null references public.profiles,attachment_id uuid not null references public.attachments,active boolean not null default true,created_at timestamptz not null default now(),closed_at timestamptz);
create unique index one_active_referral on public.referrals(submission_id) where active;
create table public.assessments(id uuid primary key default gen_random_uuid(),referral_id uuid not null references public.referrals,attachment_id uuid not null references public.attachments,actor_id uuid not null references public.profiles,outcome text not null check(outcome in ('score','revision','wrong_course','administrative_review')),score numeric(3,2) check(score>=0 and score<=1),feedback text not null check(length(feedback)>0),request_id uuid not null unique,created_at timestamptz not null default now(),check((outcome='score' and score is not null) or (outcome<>'score' and score is null)));
create unique index one_score_per_referral on public.assessments(referral_id) where outcome='score';
create table public.appeals(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles,submission_id uuid references public.submissions,subject text not null,body text not null,status text not null default 'open' check(status in ('open','reviewing','resolved')),resolution text,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.content(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('opportunities','journals','resources','news','about','privacy','policy','faq')),title text not null,description text not null,external_url text check(external_url is null or external_url ~ '^https://'),status text not null default 'draft' check(status in ('draft','published')),department_id uuid references public.departments,created_at timestamptz not null default now());
create table public.points_rules(id uuid primary key default gen_random_uuid(),activity text not null unique,points integer not null check(points>0),approved boolean not null default false);
create table public.points_ledger(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles,semester_id uuid not null references public.semesters,activity text not null,source_id uuid not null,points integer not null check(points<>0),reversal_of uuid unique references public.points_ledger,reason text not null,created_at timestamptz not null default now());
create unique index points_once on public.points_ledger(student_id,activity,source_id) where reversal_of is null;
create table public.badges(id uuid primary key default gen_random_uuid(),title text not null,minimum_points integer not null check(minimum_points>0),approved boolean not null default false);
create table public.certificates(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles,kind text not null check(kind in ('membership','attendance','participation')),event_id uuid references public.events,verification_id uuid not null unique default gen_random_uuid(),public_name text not null,issued_at timestamptz not null default now(),revoked_at timestamptz,revocation_reason text);
create table public.audit(id bigint generated always as identity primary key,actor_id uuid,action text not null,entity text not null,entity_id text,before_data jsonb,after_data jsonb,reason text,created_at timestamptz not null default now());
create index referral_instructor on public.referrals(instructor_id,active);
create index submission_student on public.submissions(student_id);
create index notification_user on public.notifications(user_id,created_at);
create index role_user on public.roles(user_id);

create function public.has_role(wanted public.app_role,scope uuid default null) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.roles r join public.profiles p on p.id=r.user_id where r.user_id=auth.uid() and r.role=wanted and r.approved and p.membership='approved' and (r.department_id is null or r.department_id=scope)); $$;
create function public.is_admin(scope uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.has_role('admin',scope); $$;
create function public.can_read_submission(sid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.submissions s join public.events e on e.id=s.event_id join public.profiles p on p.id=auth.uid() where s.id=sid and p.membership='approved' and (s.student_id=auth.uid() or public.is_admin(e.department_id) or exists(select 1 from public.referrals r where r.submission_id=s.id and r.instructor_id=auth.uid() and public.has_role('instructor',e.department_id)))); $$;
create function public.can_read_attachment(aid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.attachments a join public.submissions s on s.id=a.submission_id join public.events e on e.id=s.event_id join public.profiles p on p.id=auth.uid() where a.id=aid and p.membership='approved' and (s.student_id=auth.uid() or public.is_admin(e.department_id) or exists(select 1 from public.referrals r where r.attachment_id=a.id and r.instructor_id=auth.uid() and public.has_role('instructor',e.department_id)))); $$;
create function public.audit_change() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.audit(actor_id,action,entity,entity_id,before_data,after_data,reason) values(auth.uid(),TG_OP,TG_TABLE_NAME,coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id'),case when TG_OP<>'INSERT' then to_jsonb(old) end,case when TG_OP<>'DELETE' then to_jsonb(new) end,current_setting('utr.reason',true));return coalesce(new,old);end; $$;
create function public.on_signup() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id) values(new.id);insert into public.roles(user_id,role,approved) values(new.id,'student',true);return new;end; $$;
create trigger utr_signup after insert on auth.users for each row execute function public.on_signup();
do $$ declare t text; begin foreach t in array array['departments','profiles','roles','semesters','offerings','enrollments','policies','forms','events','event_offerings','registrations','attendance','submissions','attachments','referrals','assessments','appeals','notifications','content','points_rules','points_ledger','badges','certificates','audit'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant select on public.%I to authenticated',t);if t<>'audit' then execute format('create trigger audit_%I after insert or update or delete on public.%I for each row execute function public.audit_change()',t,t);end if;end loop;end $$;
grant select on public.events,public.content,public.departments to anon;
create policy departments_read on public.departments for select using(true);
create policy profiles_read on public.profiles for select using(id=auth.uid() or public.is_admin(department_id) or public.has_role('superadmin'));
create policy roles_read on public.roles for select using(user_id=auth.uid() or public.has_role('superadmin'));
create policy semesters_read on public.semesters for select using(auth.uid() is not null);
create policy offerings_read on public.offerings for select using(approved or instructor_id=auth.uid() or public.is_admin(department_id));
create policy enrollments_read on public.enrollments for select using(student_id=auth.uid() or exists(select 1 from public.offerings o where o.id=offering_id and (o.instructor_id=auth.uid() or public.is_admin(o.department_id))));
create policy policies_read on public.policies for select using(approved or public.has_role('admin') or public.has_role('superadmin'));
create policy forms_read on public.forms for select using(approved or public.has_role('admin'));
create policy events_read on public.events for select using(status='published' or public.is_admin(department_id));
create policy relevance_read on public.event_offerings for select using(exists(select 1 from public.events e where e.id=event_id));
create policy registration_read on public.registrations for select using(student_id=auth.uid() or exists(select 1 from public.events e where e.id=event_id and public.is_admin(e.department_id)));
create policy attendance_read on public.attendance for select using(student_id=auth.uid() or exists(select 1 from public.events e where e.id=event_id and public.is_admin(e.department_id)) or exists(select 1 from public.submissions s where s.student_id=attendance.student_id and s.event_id=attendance.event_id and public.can_read_submission(s.id)));
create policy submissions_read on public.submissions for select using(public.can_read_submission(id));
create policy attachments_read on public.attachments for select using(public.can_read_attachment(id));
create policy referrals_read on public.referrals for select using(public.can_read_submission(submission_id));
create policy assessments_read on public.assessments for select using(exists(select 1 from public.referrals r where r.id=referral_id and public.can_read_submission(r.submission_id)));
create policy appeals_read on public.appeals for select using(student_id=auth.uid() or exists(select 1 from public.profiles p where p.id=student_id and public.is_admin(p.department_id)));
create policy notifications_read on public.notifications for select using(user_id=auth.uid());
create policy content_read on public.content for select using(status='published' or public.is_admin(department_id));
create policy points_read on public.points_ledger for select using(student_id=auth.uid() or exists(select 1 from public.profiles p where p.id=student_id and public.is_admin(p.department_id)));
create policy rules_read on public.points_rules for select using(approved or public.has_role('admin'));
create policy badges_read on public.badges for select using(approved or public.has_role('admin'));
create policy certificates_read on public.certificates for select using(student_id=auth.uid() or exists(select 1 from public.profiles p where p.id=student_id and public.is_admin(p.department_id)));
create policy audit_read on public.audit for select using(public.has_role('superadmin'));

create function public.update_profile(p_name text,p_number text,p_degree text,p_department uuid,p_leaderboard boolean,p_publication boolean) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or length(p_name)>150 or length(p_number)>50 then raise exception 'invalid profile';end if;update public.profiles set display_name=p_name,student_number=p_number,degree=p_degree,department_id=p_department,leaderboard_consent=p_leaderboard,publication_consent=p_publication,membership=case when student_number is distinct from p_number or degree is distinct from p_degree or department_id is distinct from p_department then 'pending'::public.membership_state else membership end where id=auth.uid();end; $$;
create function public.register_event(p_event uuid) returns void language plpgsql security definer set search_path='' as $$ declare e public.events;begin select * into e from public.events where id=p_event for update;if not found or e.status<>'published' or not public.has_role('student',e.department_id) or now()<coalesce(e.registration_opens,e.starts_at) or now()>=coalesce(e.registration_closes,e.starts_at) then raise exception 'registration unavailable';end if;if exists(select 1 from public.registrations where event_id=p_event and student_id=auth.uid() and status='registered') then return;end if;if e.capacity is not null and (select count(*) from public.registrations where event_id=p_event and status='registered')>=e.capacity then raise exception 'capacity reached';end if;insert into public.registrations(event_id,student_id) values(p_event,auth.uid()) on conflict(event_id,student_id) do update set status='registered';end; $$;
create function public.begin_submission(p_event uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare e public.events; sid uuid; pol public.policies;begin select * into e from public.events where id=p_event for share;if not found or not e.club_approved or e.status<>'published' or e.summary_deadline is null or now()>e.summary_deadline or now()<e.ends_at or not public.has_role('student',e.department_id) then raise exception 'event not eligible';end if;if not exists(select 1 from public.attendance where event_id=p_event and student_id=auth.uid() and confirmed) then raise exception 'attendance required';end if;select * into pol from public.policies where id=e.policy_id and approved;if not found or not exists(select 1 from public.forms where id=e.form_id and approved) then raise exception 'approved policy and form required';end if;insert into public.submissions(student_id,event_id,deadline_snapshot,policy_snapshot,form_id) values(auth.uid(),p_event,e.summary_deadline,to_jsonb(pol),e.form_id) on conflict(student_id,event_id) do nothing;select id into sid from public.submissions where student_id=auth.uid() and event_id=p_event;return sid;end; $$;
create function public.add_attachment(p_submission uuid,p_id uuid,p_mime text,p_bytes integer,p_hash text) returns uuid language plpgsql security definer set search_path='' as $$ declare s public.submissions;v integer;deadline timestamptz;begin select * into s from public.submissions where id=p_submission for update;if not found or s.student_id<>auth.uid() or not public.has_role('student',(select department_id from public.events where id=s.event_id)) or s.positive_locked or s.state not in ('draft','revision_requested','zero','wrong_course') then raise exception 'upload forbidden';end if;deadline=s.deadline_snapshot;if s.state='revision_requested' then if s.policy_snapshot->>'revision_hours' is null then raise exception 'revision policy pending';end if;select greatest(deadline,max(a.created_at)+make_interval(hours=>(s.policy_snapshot->>'revision_hours')::int)) into deadline from public.assessments a join public.referrals r on r.id=a.referral_id where r.submission_id=s.id and a.outcome='revision';end if;if now()>deadline then raise exception 'deadline closed';end if;if exists(select 1 from public.attachments where id=p_id and submission_id=s.id and sha256=p_hash) then return p_id;end if;select coalesce(max(version),0)+1 into v from public.attachments where submission_id=s.id;insert into public.attachments(id,submission_id,version,object_path,mime,bytes,sha256) values(p_id,s.id,v,auth.uid()::text||'/'||s.id::text||'/'||p_id::text,p_mime,p_bytes,p_hash);return p_id;end; $$;
create function public.submit_referral(p_submission uuid,p_offering uuid,p_attachment uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare s public.submissions;o public.offerings;r public.referrals;rid uuid;deadline timestamptz;alternatives integer;begin select * into s from public.submissions where id=p_submission for update;if not found or s.student_id<>auth.uid() or s.positive_locked or s.state in ('suspended','invalidated','administrative_review','completed','positive') then raise exception 'referral forbidden';end if;if not public.has_role('student',(select department_id from public.events where id=s.event_id)) or not exists(select 1 from public.attendance where event_id=s.event_id and student_id=auth.uid() and confirmed) or not exists(select 1 from public.events where id=s.event_id and status='published' and club_approved) then raise exception 'eligibility changed';end if;select * into o from public.offerings where id=p_offering and approved;if not found or not exists(select 1 from public.semesters where id=o.semester_id and (now() at time zone 'Asia/Tehran')::date between starts_on and ends_on) or not exists(select 1 from public.enrollments where student_id=auth.uid() and offering_id=o.id and approved) or not exists(select 1 from public.event_offerings where event_id=s.event_id and offering_id=o.id) or not exists(select 1 from public.roles x join public.profiles p on p.id=x.user_id where x.user_id=o.instructor_id and x.role='instructor' and x.approved and p.membership='approved' and (x.department_id is null or x.department_id=o.department_id)) then raise exception 'course or instructor not eligible';end if;if not exists(select 1 from public.attachments where id=p_attachment and submission_id=s.id and safety='clean') then raise exception 'file not ready';end if;select * into r from public.referrals where submission_id=s.id and active for update;if found and s.state<>'revision_requested' then if r.attachment_id=p_attachment and r.offering_id=p_offering then return r.id;end if;raise exception 'active referral exists';end if;deadline=s.deadline_snapshot;if s.state='revision_requested' then if r.offering_id<>p_offering or s.policy_snapshot->>'revision_hours' is null then raise exception 'revision must stay with instructor or policy pending';end if;select greatest(deadline,max(created_at)+make_interval(hours=>(s.policy_snapshot->>'revision_hours')::int)) into deadline from public.assessments where referral_id=r.id and outcome='revision';elsif s.state in ('zero','wrong_course') then if s.policy_snapshot->>'referral_hours' is null then raise exception 'referral policy pending';end if;select greatest(deadline,max(a.created_at)+make_interval(hours=>(s.policy_snapshot->>'referral_hours')::int)) into deadline from public.assessments a join public.referrals rr on rr.id=a.referral_id where rr.submission_id=s.id;select count(*) into alternatives from public.referrals where submission_id=s.id;if not coalesce((s.policy_snapshot->>'unlimited_alternatives')::boolean,false) and (s.policy_snapshot->>'max_alternatives' is null or alternatives>(s.policy_snapshot->>'max_alternatives')::int) then raise exception 'alternative referral limit or pending policy';end if;if exists(select 1 from public.referrals where submission_id=s.id and instructor_id=o.instructor_id) then raise exception 'choose another instructor';end if;end if;if now()>deadline then raise exception 'deadline closed';end if;if s.state='revision_requested' then update public.referrals set attachment_id=p_attachment where id=r.id;rid=r.id;else insert into public.referrals(submission_id,offering_id,instructor_id,attachment_id) values(s.id,o.id,o.instructor_id,p_attachment) returning id into rid;end if;update public.submissions set state='submitted' where id=s.id;insert into public.notifications(user_id,title,body) values(o.instructor_id,'خلاصه جدید برای ارزیابی','یک خلاصه برای درس شما ارسال شد.');return rid;end; $$;
create function public.assess(p_referral uuid,p_attachment uuid,p_outcome text,p_score numeric,p_feedback text,p_request uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare r public.referrals;s public.submissions;aid uuid;begin select submission_id into aid from public.referrals where id=p_referral;select * into s from public.submissions where id=aid for update;select * into r from public.referrals where id=p_referral for update;if r.instructor_id is distinct from auth.uid() or not public.has_role('instructor',(select department_id from public.offerings where id=r.offering_id)) then raise exception 'assessment forbidden';end if;select id into aid from public.assessments where request_id=p_request and referral_id=p_referral and actor_id=auth.uid() and attachment_id=p_attachment and outcome=p_outcome and score is not distinct from p_score and feedback=p_feedback;if found then return aid;end if;if not r.active or r.attachment_id<>p_attachment or s.positive_locked or s.state not in ('submitted','under_review') then raise exception 'stale assessment';end if;if not exists(select 1 from public.attendance where event_id=s.event_id and student_id=s.student_id and confirmed) then raise exception 'attendance dispute requires administration';end if;if p_score is not null and (p_score<0 or p_score>1 or p_score<>round(p_score,2)) then raise exception 'invalid decimal score';end if;insert into public.assessments(referral_id,attachment_id,actor_id,outcome,score,feedback,request_id) values(r.id,p_attachment,auth.uid(),p_outcome,p_score,p_feedback,p_request) returning id into aid;update public.submissions set state=case when p_outcome='score' and p_score>0 then 'positive'::public.submission_state when p_outcome='score' then 'zero'::public.submission_state when p_outcome='revision' then 'revision_requested'::public.submission_state when p_outcome='wrong_course' then 'wrong_course'::public.submission_state else 'administrative_review'::public.submission_state end,positive_locked=positive_locked or (p_outcome='score' and p_score>0) where id=s.id;if p_outcome<>'revision' then update public.referrals set active=false,closed_at=now() where id=r.id;end if;insert into public.notifications(user_id,title,body) values(s.student_id,'نتیجه بررسی خلاصه','نتیجه و بازخورد در پرونده شما ثبت شد.');return aid;end; $$;

-- Storage is private; no client UPDATE/DELETE and no user-generated public URL.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('summaries','summaries',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']),('forms','forms',false,10485760,array['application/pdf']) on conflict(id) do nothing;
create policy summary_select on storage.objects for select to authenticated using(bucket_id='summaries' and exists(select 1 from public.attachments a where a.object_path=name and public.can_read_attachment(a.id)));
create policy summary_insert on storage.objects for insert to authenticated with check(bucket_id='summaries' and exists(select 1 from public.attachments a join public.submissions s on s.id=a.submission_id where a.object_path=name and s.student_id=auth.uid() and not s.positive_locked and a.safety='pending'));
create policy form_select on storage.objects for select to authenticated using(bucket_id='forms' and exists(select 1 from public.forms f where f.object_path=name and f.approved));
revoke all on all functions in schema public from public,anon,authenticated;
grant execute on function public.has_role(public.app_role,uuid),public.is_admin(uuid),public.can_read_submission(uuid),public.can_read_attachment(uuid),public.update_profile(text,text,text,uuid,boolean,boolean),public.register_event(uuid),public.begin_submission(uuid),public.add_attachment(uuid,uuid,text,integer,text),public.submit_referral(uuid,uuid,uuid),public.assess(uuid,uuid,text,numeric,text,uuid) to authenticated;
-- Anonymous read policies call is_admin, which always returns false without identity.
grant execute on function public.is_admin(uuid),public.has_role(public.app_role,uuid) to anon;
commit;
